#include <cstdio>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){int n,k;scanf("%d %d",&n,&k);
priority_queue<long long,vector<long long>,greater<long long>>pq;
bool first=true;
for(int i=0;i<n;++i){long long x;scanf("%lld",&x);
pq.push(x);
if((int)pq.size()>k)pq.pop();
if(i>=k-1){if(!first)printf(" ");printf("%lld",pq.top());first=false;}}
printf("\n");return 0;}

